class Solution:
    def longestSubstring(self, s):
        vowels = set('aeiou')
        n = len(s)

        prefix = [0] * (n + 1)
        for i in range(n):
            if s[i] in vowels:
                prefix[i+1] = prefix[i] - 2
            else:
                prefix[i+1] = prefix[i] + 1

        max_len = -1
        start_idx = -1

        for l in range(n):
            for r in range(l, n):
                if prefix[r+1] - prefix[l] >= 0:
                    length = r - l + 1
                    if length > max_len or (length == max_len and l < start_idx):
                        max_len = length
                        start_idx = l

        if max_len == -1:
            return "-1"
        return s[start_idx:start_idx + max_len]
